import json

# The issue: I was iterating from inner to outer, which caused outer colors
# to OVERWRITE inner colors. I need to iterate from OUTER to INNER.

n_rows, n_cols = 20, 19
output = [[0]*n_cols for _ in range(n_rows)]

# === LEFT STRUCTURE ===
# Output colors (reversed from input): 3s(innermost) -> 6s -> 1s -> 4s(outermost)
# Write from outermost to innermost:

# 4s outermost: rows 1-9, cols 1-10
for r in range(1, 10):
    for c in range(1, 11):
        output[r][c] = 4

# 1s: rows 3-7, cols 3-8 (overwrites 4s in that inner area)
for r in range(3, 8):
    for c in range(3, 9):
        output[r][c] = 1

# 6s: rows 4-6, cols 4-7 (overwrites 1s)
for r in range(4, 7):
    for c in range(4, 8):
        output[r][c] = 6

# 3s innermost: row 5, cols 5-6 (overwrites 6s)
for r in range(5, 6):
    for c in range(5, 7):
        output[r][c] = 3

# === RIGHT STRUCTURE ===
# Output colors (reversed): 8s(innermost) -> 4s -> 5s(outermost)

# 8s outermost: rows 4-9, cols 13-18
for r in range(4, 10):
    for c in range(13, 19):
        output[r][c] = 8

# 4s: rows 5-8, cols 14-17 (overwrites 8s)
for r in range(5, 9):
    for c in range(14, 18):
        output[r][c] = 4

# 5s innermost: rows 6-7, cols 15-16 (overwrites 4s)
for r in range(6, 8):
    for c in range(15, 17):
        output[r][c] = 5

# === BOTTOM STRUCTURE ===
# Output colors (reversed): 6s(innermost) -> 8s -> 2s -> 4s -> 3s(outermost)

# 3s outermost: rows 11-19, cols 3-15
for r in range(11, 20):
    for c in range(3, 16):
        output[r][c] = 3

# 4s: rows 12-18, cols 4-14 (overwrites 3s)
for r in range(12, 19):
    for c in range(4, 15):
        output[r][c] = 4

# 2s: rows 13-17, cols 5-13 (overwrites 4s)
for r in range(13, 18):
    for c in range(5, 14):
        output[r][c] = 2

# 8s: rows 14-16, cols 6-12 (overwrites 2s)
for r in range(14, 17):
    for c in range(6, 13):
        output[r][c] = 8

# 6s innermost: row 15, cols 7-11 (overwrites 8s)
for r in range(15, 16):
    for c in range(7, 12):
        output[r][c] = 6

# Print result
print("Final output grid:")
for r, row in enumerate(output):
    print(f"Row {r}: {row}")

# Submit
action_data = {"action": "submit", "grid": output}
print(json.dumps(action_data))

